import React, { useState, useEffect } from 'react';

function App() {
  // --- STATE (HAFIZA) YÖNETİMİ ---
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); // Rota listemiz burada tutuluyor
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  // Pencerelerin açık/kapalı durumu
  const [seciliMekan, setSeciliMekan] = useState(null); // Detay penceresi
  const [listeAcik, setListeAcik] = useState(false);    // Rota listesi penceresi

  // Verileri Backend'den Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(Array.isArray(data) ? data : []))
      .catch(err => console.error("Bağlantı Hatası:", err));
  }, []);

  // --- ROTA EKLE / ÇIKAR FONKSİYONU ---
  const favoriEkleCikar = (e, mekan) => {
    e.stopPropagation(); // Tıklamanın karta geçmesini engeller (Sadece buton çalışır)

    setFavoriler((mevcutListe) => {
      const listedeVarMi = mevcutListe.some(item => item.id === mekan.id);

      if (listedeVarMi) {
        // Varsa listeden çıkar
        return mevcutListe.filter(item => item.id !== mekan.id);
      } else {
        // Yoksa listeye ekle (Süre bilgisini sayıya çevirerek)
        return [...mevcutListe, { ...mekan, sure: Number(mekan.sure) || 0 }];
      }
    });
  };

  // --- TOPLAM SÜRE HESAPLAMA ---
  const toplamSure = favoriler.reduce((toplam, mekan) => toplam + (Number(mekan.sure) || 0), 0);
  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  // Filtreleme İşlemi
  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (Number(m.sure) || 0) <= Number(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      {/* --- CSS STİLLERİ (GÖMÜLÜ VE GARANTİ) --- */}
      <style>{`
        body { font-family: 'Poppins', sans-serif; background-color: #f8f9fa; margin: 0; padding: 20px; }
        .header { text-align: center; margin-bottom: 30px; color: #1a4d6e; }

        /* Özet Barı (Tıklanabilir) */
        .summary-bar { 
          background: #1a4d6e; color: white; padding: 15px 30px; 
          border-radius: 50px; display: flex; justify-content: space-around; 
          margin-bottom: 30px; font-weight: 600; cursor: pointer; user-select: none;
          box-shadow: 0 4px 15px rgba(26, 77, 110, 0.3); transition: transform 0.2s;
        }
        .summary-bar:active { transform: scale(0.98); }
        .summary-bar:hover { background: #153e5c; }

        .grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 25px; }
        .controls { display: flex; justify-content: center; gap: 10px; margin-bottom: 25px; flex-wrap: wrap; }

        /* Kart Tasarımı */
        .card {
          width: 280px; background: white; border-radius: 20px;
          overflow: hidden; box-shadow: 0 5px 15px rgba(0,0,0,0.05);
          cursor: pointer; display: flex; flex-direction: column;
          transition: all 0.3s ease; border: 2px solid transparent; box-sizing: border-box;
        }
        .card:hover { transform: translateY(-5px); border-color: #00c2cb; box-shadow: 0 10px 25px rgba(0, 194, 203, 0.15); }

        .card-image-container { height: 180px; position: relative; padding: 10px; }
        .card-img { width: 100%; height: 100%; object-fit: cover; border-radius: 15px; }
        .badge { position: absolute; top: 15px; right: 15px; background: rgba(0,0,0,0.6); color: white; padding: 4px 10px; border-radius: 8px; font-size: 11px; backdrop-filter: blur(4px); }
        .card-content { padding: 15px; flex-grow: 1; display: flex; flex-direction: column; justify-content: space-between; }

        /* Butonlar */
        .btn-action {
          width: 100%; padding: 10px; border-radius: 20px;
          border: 1px solid #1a4d6e; background: transparent;
          color: #1a4d6e; font-weight: 600; cursor: pointer;
          margin-top: 10px; transition: all 0.3s;
          display: flex; justify-content: center; align-items: center; gap: 5px;
        }
        .btn-action:hover { background: #1a4d6e; color: white; }
        .btn-remove { border-color: #e74c3c; color: #e74c3c; }
        .btn-remove:hover { background: #e74c3c; color: white; }

        /* Modal (Pencere) */
        .modal-overlay {
          position: fixed; top: 0; left: 0; right: 0; bottom: 0;
          background: rgba(0,0,0,0.7); z-index: 1000;
          display: flex; justify-content: center; align-items: center;
          animation: fadeIn 0.3s;
        }
        .modal-content {
          background: white; padding: 25px; border-radius: 20px;
          max-width: 450px; width: 90%; position: relative;
          box-shadow: 0 10px 30px rgba(0,0,0,0.3); text-align: center;
          animation: slideUp 0.3s;
        }
        .close-btn { position: absolute; top: 15px; right: 15px; background: #f1f1f1; border: none; width: 30px; height: 30px; border-radius: 50%; cursor: pointer; font-weight: bold; }
        .liste-item { display: flex; justify-content: space-between; padding: 12px; border-bottom: 1px solid #eee; align-items: center; }
        .liste-item:last-child { border-bottom: none; }

        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { transform: translateY(20px); } to { transform: translateY(0); } }
      `}</style>

      {/* --- BAŞLIK --- */}
      <div className="header">
        <h1>🌴 Antalya Rota Asistanı</h1>
      </div>

      {/* --- KONTROLLER --- */}
      <div className="controls">
        <input type="number" className="search-input" placeholder="Maks. Süre (dk)" 
          value={maxSure} onChange={(e) => setMaxSure(e.target.value)} 
          style={{padding: '10px 20px', borderRadius: '25px', border: '1px solid #ddd', outline: 'none'}} />

        {['Hepsi', 'Tarih', 'Doğa', 'Yemek', 'Eğlence'].map(k => (
          <button key={k} onClick={() => setFiltre(k)}
            style={{
              padding: '8px 20px', borderRadius: '25px', border: 'none', cursor: 'pointer',
              background: filtre === k ? '#1a4d6e' : 'white', 
              color: filtre === k ? 'white' : '#666',
              boxShadow: '0 2px 5px rgba(0,0,0,0.05)'
            }}
          >
            {k}
          </button>
        ))}
      </div>

      {/* --- ÖZET BARI (TIKLANABİLİR) --- */}
      <div className="summary-bar" onClick={() => setListeAcik(true)} title="Listenin detayını görmek için tıkla">
        <div style={{display: 'flex', alignItems: 'center', gap: '8px'}}>
           <span>🎒</span> 
           <span>Rotam: {favoriler.length} Yer</span>
        </div>
        <div style={{display: 'flex', alignItems: 'center', gap: '8px'}}>
           <span>⏱️</span>
           <span>Toplam: {saat}sa {dakika}dk</span>
        </div>
        <span style={{fontSize: '12px', background: 'rgba(255,255,255,0.2)', padding: '2px 8px', borderRadius: '10px'}}>Listeyi Gör 👁️</span>
      </div>

      {/* --- KARTLAR --- */}
      <div className="grid">
        {filtrelenmis.map(m => {
          const seciliMi = favoriler.some(f => f.id === m.id);
          return (
            <div key={m.id} className="card" onClick={() => setSeciliMekan(m)}>
              <div className="card-image-container">
                <img src={m.resim} alt={m.ad} className="card-img" />
                <span className="badge">{m.kategori}</span>
              </div>
              <div className="card-content">
                <h3 style={{margin: '0 0 5px 0', color: '#1a4d6e', fontSize: '16px'}}>{m.ad}</h3>
                <div style={{fontSize: '13px', color: '#7f8c8d', display: 'flex', justifyContent: 'space-between'}}>
                   <span>📍 {m.bolge}</span>
                   <span>⏳ {m.sure} dk</span>
                </div>
                {/* Ekle/Çıkar Butonu */}
                <button 
                  className={`btn-action ${seciliMi ? 'btn-remove' : ''}`}
                  onClick={(e) => favoriEkleCikar(e, m)}
                >
                  {seciliMi ? 'Rotadan Çıkar ✕' : 'Rotaya Ekle ➜'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* --- MODAL 1: MEKAN DETAYI --- */}
      {seciliMekan && (
        <div className="modal-overlay" onClick={() => setSeciliMekan(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setSeciliMekan(null)}>✕</button>
            <img src={seciliMekan.resim} alt={seciliMekan.ad} style={{width: '100%', borderRadius: '15px', height: '200px', objectFit: 'cover'}} />
            <h2 style={{color: '#1a4d6e', marginTop: '15px'}}>{seciliMekan.ad}</h2>
            <p style={{color: '#666', lineHeight: '1.6'}}>
              Bu harika mekan <strong>{seciliMekan.bolge}</strong> bölgesinde seni bekliyor. 
              Gezmek için ortalama <strong>{seciliMekan.sure} dakika</strong> ayırmalısın.
            </p>
            <span style={{background: '#e0f2f1', color: '#009688', padding: '5px 15px', borderRadius: '15px', fontSize: '14px', fontWeight: 'bold'}}>
              {seciliMekan.kategori}
            </span>
          </div>
        </div>
      )}

      {/* --- MODAL 2: ROTA LİSTESİ (ÇALIŞMAYAN KISIM BURASIYDI) --- */}
      {listeAcik && (
        <div className="modal-overlay" onClick={() => setListeAcik(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setListeAcik(false)}>✕</button>
            <h3 style={{color: '#1a4d6e', borderBottom: '2px solid #eee', paddingBottom: '10px'}}>🎒 Rota Listen</h3>

            <div style={{maxHeight: '300px', overflowY: 'auto', textAlign: 'left', marginTop: '10px'}}>
              {favoriler.length === 0 ? (
                <div style={{padding: '20px', color: '#999'}}>Henüz rotana bir yer eklemedin.</div>
              ) : (
                favoriler.map(fav => (
                  <div key={fav.id} className="liste-item">
                    <div>
                      <div style={{fontWeight: '600', color: '#333'}}>{fav.ad}</div>
                      <div style={{fontSize: '12px', color: '#888'}}>{fav.bolge}</div>
                    </div>
                    <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                      <span style={{color: '#1a4d6e', fontWeight: 'bold'}}>{fav.sure} dk</span>
                      <button 
                        onClick={(e) => favoriEkleCikar(e, fav)}
                        style={{background: '#ffebee', color: '#c62828', border: 'none', borderRadius: '50%', width: '24px', height: '24px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px'}}
                      >
                        ✕
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>

            {favoriler.length > 0 && (
              <div style={{marginTop: '20px', background: '#f1f8e9', padding: '10px', borderRadius: '10px', color: '#33691e'}}>
                <strong>Toplam Süre: {saat} saat {dakika} dakika</strong>
              </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
}

export default App;
